                createFieldVelikost(options) {
                    var _this = this;
                    var units = [
                        { value: 0, caption: "B" },
                        { value: 1, caption: "kB" },
                        { value: 2, caption: "MB" },
                        { value: 3, caption: "GB" },
                        { value: 4, caption: "TB" }
                    ];
                    //this.currentUnits[options.fieldName] = options.initialValueUnit;
                    var numberValue = parseInt(options.initialValueNumber);
                    var initialValue = 0;
                    if (numberValue != 0) {
                        if (numberValue < Math.pow(1000, 1))
                            options.initialValueUnit = 0;
                        else if (numberValue < Math.pow(1000, 2))
                            options.initialValueUnit = 1;
                        else if (numberValue < Math.pow(1000, 3))
                            options.initialValueUnit = 2;
                        else if (numberValue < Math.pow(1000, 4))
                            options.initialValueUnit = 3;
                        else
                            options.initialValueUnit = 4;
                        initialValue = parseInt(options.initialValueNumber) / Math.pow(1000, options.initialValueUnit);
                    }
                    this.form.addRow({
                        label: options.caption,
                        hint: options.hint
                    }).addField("gnumberbox", "w-8", {
                        name: options.fieldName,
                        flag: "required",
                        validators: [new Gordic.Validators.Required({ stopping: true })],
                        thousandsSeparator: " ",
                        rounding: Decimal.ROUND_HALF_UP,
                        returnType: "number",
                        initialValue: initialValue,
                        model: function (op, dto, opt) {
                            switch (op) {
                                case "collect":
                                    var field = $(this);
                                    var fieldName = field[0].dataset["field"] ?? "";
                                    var value = field.gfield("getValue");
                                    var units = _this.cnt.findFields(`${fieldName}_units`).gfield("getValue");
                                    if (value && units) {
                                        dto[fieldName] = value * Math.pow(1000, units.value);
                                    }
                                    else {
                                        dto[fieldName] = 0;
                                    }
                                    break;
                            }
                        },
                        decimals: 2,
                        disabled: true
                    }).addField("gselectbox", "w-4", {
                        name: `${options.fieldName}_units`,
                        flag: "required",
                        validators: [new Gordic.Validators.Required({ stopping: true })],
                        data: units,
                        dropdown: true,
                        graphicInput: "oninput",
                        itemTemplate: "<b>{caption}</b>",
                        initialValue: units[options.initialValueUnit],
                        disabled: true,
                        change: function (ev, ctx) {
                            var field = $(this);
                            field.gfield("validate");
                            if (ctx.value.value != null && ctx.value.value != undefined) {
                                var fieldName = field[0].dataset["field"]?.replace("_units", "") ?? "";
                                var nasobek = _this.currentUnits[fieldName] - ctx.value.value;
                                var fieldValue = _this.cnt.findFields(fieldName).gfield("getValue");
                                if (fieldValue != null && fieldValue != undefined) {
                                    _this.cnt.findFields(fieldName).gfield("setValue", (fieldValue * Math.pow(1000, nasobek)));
                                    _this.currentUnits[fieldName] = ctx.value.value;
                                }
                            }
                        }
                    });
                }
