                createVazby() {
                    this.vazbyObj = [];
                    this.vazby.forEach((item) => {
                        var canCreate = item.metadata?.data_right?.Create ?? false;
                        let data = [];
                        if (item.data) {
                            item.data.forEach((item2) => {
                                let obj = item2;
                                obj["check"] = true;
                                data.push(obj);
                            });
                        }
                        this.vazbyObj.push({
                            bussinessObj: item.bussinessObj,
                            canCreate: canCreate,
                            check: canCreate,
                            caption: item.caption,
                            metadata: item.metadata ?? {},
                            data: data,
                            columnOrder: item.columnOrder ?? null,
                            gridFormat: item.gridFormat ?? null,
                            columnsBeforeSave: item.columnsBeforeSave,
                            updateGridFormat: item.updateGridFormat
                        });
                    });
                }
