                function updateLastView(cnt) {
                    var globalSettingLastLists = "Global.core.viewLastLists";
                    if (cnt.parentContent) {
                        if (cnt.taskId) {
                            if (cnt.globalSettings) {
                                var lastviewedArray = cnt.globalSettings.getDef(globalSettingLastLists, []);
                                if (!Array.isArray(lastviewedArray)) {
                                    cnt.globalSettings.set(globalSettingLastLists, []);
                                    lastviewedArray = [];
                                }
                                var selectedAction = findInMenuParams(cnt.taskId ?? "", $(".main-tasklist").gtasklist("getParams"));
                                var novaPolozka = {
                                    name: selectedAction.name,
                                    icon: selectedAction.icon,
                                    datum: new Date().toISOString(),
                                    caption: selectedAction.caption
                                };
                                var indexies = [];
                                for (var i = 0; i < lastviewedArray.length; i++) {
                                    if (lastviewedArray[i].name == novaPolozka.name)
                                        indexies.push(i);
                                }
                                if (indexies.length > 0) {
                                    indexies.sort((a, b) => b - a).forEach((index) => {
                                        lastviewedArray.splice(index, 1);
                                    });
                                }
                                else
                                    lastviewedArray.splice(9);
                                lastviewedArray.unshift(novaPolozka);
                                cnt.globalSettings.set(globalSettingLastLists, lastviewedArray);
                            }
                        }
                    }
                }
                GAdxGlobals.updateLastView = updateLastView;
